(function(root,factory){if(typeof module!=='undefined')module.exports=factory;else root.ClinicCustomerCenter=factory;})(typeof window!=='undefined'?window:this,function(){
 const faq=[["진료 상담","온라인 상담은 어디에서 작성하나요?","눈여겨볼 정보 메뉴의 온라인 상담 또는 화면 옆 퀵바의 온라인상담을 선택해 주세요. 상담 게시판 아래 작성란에서 문의 내용을 입력할 수 있습니다."],["진료 상담","작성한 상담 내용은 다른 사람도 볼 수 있나요?","모든 상담은 비밀글로 작성됩니다. 목록에는 문의 분야와 가려진 이름, 날짜, 답변 상태만 표시하며 내용은 작성 시 설정한 비밀번호 또는 관리자 로그인으로 확인합니다."],["진료 상담","등록한 상담의 답변은 어디에서 확인하나요?","온라인 상담 페이지의 게시판에서 본인 글을 선택하고 비밀번호를 입력해 주세요. 관리자가 답변하면 답변완료로 표시되며 글 안에서 내용을 확인할 수 있습니다."],["예약·내원","온라인 상담을 작성하면 진료 예약도 확정되나요?","온라인 상담 작성은 진료 예약 확정과는 다릅니다. 방문 일정과 접수 가능 여부는 051-325-1919로 확인해 주세요."]].concat([['예약·내원','진료시간은 어떻게 되나요?','평일은 오전 9시부터 오후 6시까지, 토요일은 오전 9시부터 오후 1시까지 진료합니다. 점심시간은 오후 1시부터 2시까지이며 일요일과 공휴일은 휴진입니다.'],['예약·내원','오늘 방문하고 싶은데 예약이 필요한가요?','당일 진료와 접수 가능 여부는 051-325-1919로 확인해 주세요. 진료 상황과 검사 종류에 따라 대기시간이 달라질 수 있습니다.'],['예약·내원','병원은 어디에 있나요?','부산 사상구 가야대로 276 엠스퀘어메디컬센터 9층입니다. 부산 지하철 2호선 주례역 5번 출구 앞, 주례농협 옆에 있습니다.'],['검사 안내','검사하러 갈 때 무엇을 가져가면 되나요?','신분증과 사용 중인 안경, 복용약 정보, 이전 검사 자료가 있다면 준비해 주세요. 검사별 준비사항은 방문 전 전화로 안내받으실 수 있습니다.'],['진료 상담','수술 비용이나 치료 방법을 온라인으로 알 수 있나요?','일반적인 안내는 가능하지만, 정확한 치료 방법과 비용은 검사 결과에 따라 달라집니다. 현재 눈 상태를 확인한 뒤 의료진과 상담해 주세요.']]);
 return `<section class="support-content wrap"><section id="support-faq" class="support-section"><div class="support-heading"><div><p class="eyebrow">Q&amp;A</p><h2>자주 묻는 질문</h2></div></div><div class="support-faq-filters" role="group" aria-label="FAQ 분류">${['전체','예약·내원','검사 안내','진료 상담'].map((c,i)=>`<button type="button" data-faq-filter="${c}" aria-pressed="${i===0}">${c}</button>`).join('')}</div><div>${faq.map(([c,q,a])=>`<details class="support-faq-item" data-faq-category="${c}"><summary><span>Q</span>${q}<b aria-hidden="true">+</b></summary><div><span>A</span><p>${a}</p></div></details>`).join('')}</div></section></section>`;
});
